/**
 * RPC/program plumbing shared by hooks. Kept deliberately small: the
 * Anchor IDL is generated by `anchor build` into `target/idl/meridian.json`
 * at build time and is not guaranteed to exist in the web build context, so
 * loading it and constructing the on-chain program client is left to the
 * hooks that need it via `loadProgram`, which takes the IDL as a parameter
 * instead of reading the file itself.
 */

import { Connection, PublicKey } from "@solana/web3.js";
import { Program, type Idl, type Provider } from "@anchor-lang/core";

const RPC_ENDPOINT = process.env.NEXT_PUBLIC_RPC_URL ?? "https://api.devnet.solana.com";
const WS_ENDPOINT = process.env.NEXT_PUBLIC_WS_URL ?? "wss://api.devnet.solana.com";

const PROGRAM_ID_RAW = process.env.NEXT_PUBLIC_PROGRAM_ID ?? "11111111111111111111111111111111";

/** The deployed Meridian program id, from `NEXT_PUBLIC_PROGRAM_ID`. */
export const PROGRAM_ID = new PublicKey(PROGRAM_ID_RAW);

let cachedConnection: Connection | null = null;

/** A shared `Connection` to the RPC endpoint configured via `NEXT_PUBLIC_RPC_URL`. */
export function getConnection(): Connection {
  if (cachedConnection === null) {
    cachedConnection = new Connection(RPC_ENDPOINT, { commitment: "confirmed", wsEndpoint: WS_ENDPOINT });
  }
  return cachedConnection;
}

/** Minimal shape of an Anchor provider; satisfies `@anchor-lang/core`'s `Provider` interface. */
export type AnchorProviderLike = Provider;

/** Builds the on-chain program client from a pre-loaded IDL and an Anchor provider. */
export function loadProgram(idl: Idl, provider: AnchorProviderLike): Program {
  return new Program(idl, provider);
}
